// Turn a local File or an already-saved /media/uploads path into a pool asset.
// Skips the video-normalize pass: generated bytes are already a playable master.

import type { MediaAsset } from '../../editor/types';
import { probeMediaFile, probeMediaSource } from '../../media/mediaProbe';
import { uploadFile } from '../../media/uploadTransport';
import type { GeneratedKind } from './libtvExtract';

function assetId(): string {
  const uuid = typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `a_${Date.now()}`;
  return `desk_${uuid}`;
}

export async function stageGeneratedFile(file: File, fps: number, kind: GeneratedKind): Promise<MediaAsset> {
  const meta = await probeMediaFile(file, kind, fps);
  const uploaded = await uploadFile(file);
  return {
    id: assetId(),
    name: file.name,
    sourceFilename: file.name,
    kind,
    src: uploaded.src,
    sourceContentHash: uploaded.sourceContentHash,
    durationInFrames: Math.max(1, meta.durationInFrames),
    width: meta.width,
    height: meta.height,
    sourceSize: file.size,
  };
}

export async function stageUploadedSrc(
  src: string,
  name: string,
  kind: GeneratedKind,
  fps: number,
): Promise<MediaAsset> {
  const meta = await probeMediaSource(src, kind, fps);
  return {
    id: assetId(),
    name,
    sourceFilename: name,
    kind,
    src,
    durationInFrames: Math.max(1, meta.durationInFrames),
    width: meta.width,
    height: meta.height,
  };
}
